    test('routes file_info', () async {
      final file = File('${tempDir.path}/i.txt')..writeAsStringSync('x');
      final info = await executor.execute('file_info', {'path': file.path})
          as Map<String, dynamic>;
      expect(info['exists'], isTrue);
    });
  });
}

